#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\nVERIFICADOR DE CORRECCIONES APLICADAS AL CRM LEGAL\n=================================================\n\nEste script verifica que las correcciones específicas se aplicaron correctamente.\n\"\"\"\n\nimport os\nimport sqlite3\n\ndef verificar_update_case():\n    \"\"\"Verificar que la corrección de update_case se aplicó\"\"\"\n    print(\"🔍 VERIFICANDO CORRECCIÓN update_case()\")\n    print(\"=\" * 45)\n    \n    if not os.path.exists('casos_ui.py'):\n        print(\"❌ casos_ui.py no encontrado\")\n        return False\n    \n    with open('casos_ui.py', 'r', encoding='utf-8') as f:\n        contenido = f.read()\n    \n    # Buscar la línea corregida\n    if 'self.db_crm.update_case(case_id, caratula,' in contenido:\n        print(\"✅ update_case() corregido: ya no incluye cliente_id\")\n        \n        # Verificar que no incluye etiquetas_str\n        if 'etiquetas_str)' not in contenido.split('update_case')[1].split(')')[0]:\n            print(\"✅ update_case() corregido: ya no incluye etiquetas_str\")\n            return True\n        else:\n            print(\"❌ update_case() aún incluye etiquetas_str\")\n            return False\n    else:\n        print(\"❌ update_case() no corregido: aún incluye cliente_id\")\n        return False\n\ndef verificar_layout_calendario():\n    \"\"\"Verificar que la corrección del layout se aplicó\"\"\"\n    print(\"\\n🔍 VERIFICANDO LAYOUT CALENDARIO\")\n    print(\"=\" * 40)\n    \n    if not os.path.exists('main_app_refactorizado.py'):\n        print(\"❌ main_app_refactorizado.py no encontrado\")\n        return False\n    \n    with open('main_app_refactorizado.py', 'r', encoding='utf-8') as f:\n        contenido = f.read()\n    \n    # Buscar las líneas corregidas\n    weight_2_found = False\n    weight_1_found = False\n    \n    lineas = contenido.split('\\n')\n    for linea in lineas:\n        if 'rowconfigure(0, weight=2)' in linea and 'Casos' in linea:\n            weight_2_found = True\n            print(\"✅ Fila 0 (casos): weight=2 configurado (2/3 del espacio)\")\n        elif 'rowconfigure(1, weight=1)' in linea and 'Audiencias' in linea:\n            weight_1_found = True\n            print(\"✅ Fila 1 (audiencias): weight=1 configurado (1/3 del espacio)\")\n    \n    if weight_2_found and weight_1_found:\n        print(\"✅ Layout calendario corregido: proporción 2/3 y 1/3\")\n        return True\n    else:\n        print(f\"❌ Layout calendario no corregido: weight=2 {weight_2_found}, weight=1 {weight_1_found}\")\n        return False\n\ndef verificar_base_datos():\n    \"\"\"Verificar el estado de la base de datos\"\"\"\n    print(\"\\n🔍 VERIFICANDO BASE DE DATOS\")\n    print(\"=\" * 35)\n    \n    if not os.path.exists('crm_legal.db'):\n        print(\"⚠️ crm_legal.db no encontrada (esto es normal si no existe aún)\")\n        return True  # No es un error crítico\n    \n    try:\n        conn = sqlite3.connect('crm_legal.db')\n        cursor = conn.cursor()\n        \n        # Verificar estructura de tabla etiquetas\n        cursor.execute(\"PRAGMA table_info(etiquetas)\")\n        columnas = [col[1] for col in cursor.fetchall()]\n        \n        print(f\"📋 Columnas en tabla etiquetas: {columnas}\")\n        \n        if 'fecha_creacion' in columnas:\n            print(\"✅ Columna fecha_creacion existe\")\n            \n            # Probar consulta\n            try:\n                cursor.execute(\"SELECT nombre_etiqueta, fecha_creacion FROM etiquetas LIMIT 1\")\n                resultado = cursor.fetchone()\n                print(f\"✅ Consulta con fecha_creacion exitosa: {resultado}\")\n                conn.close()\n                return True\n            except Exception as e:\n                print(f\"❌ Error en consulta con fecha_creacion: {e}\")\n                conn.close()\n                return False\n        else:\n            print(\"⚠️ Columna fecha_creacion no existe (necesita migración)\")\n            conn.close()\n            return False\n            \n    except Exception as e:\n        print(f\"❌ Error conectando a BD: {e}\")\n        return False\n\ndef verificar_archivos_pestanas():\n    \"\"\"Verificar el estado de los archivos de pestañas\"\"\"\n    print(\"\\n🔍 VERIFICANDO ARCHIVOS PESTAÑAS\")\n    print(\"=\" * 40)\n    \n    archivos = ['seguimiento_ui.py', 'partes_ui.py', 'tareas_ui.py']\n    archivos_encontrados = 0\n    \n    for archivo in archivos:\n        if os.path.exists(archivo):\n            print(f\"✅ {archivo} encontrado\")\n            archivos_encontrados += 1\n            \n            # Contar botones deshabilitados\n            with open(archivo, 'r', encoding='utf-8') as f:\n                contenido = f.read()\n            \n            botones_disabled = contenido.count('state=tk.DISABLED')\n            if botones_disabled > 0:\n                print(f\"   ⚠️ {botones_disabled} botones con state=tk.DISABLED encontrados\")\n                print(f\"   📋 Esto puede ser normal si se habilitan dinámicamente\")\n            else:\n                print(f\"   ✅ No hay botones permanentemente deshabilitados\")\n        else:\n            print(f\"❌ {archivo} no encontrado\")\n    \n    return archivos_encontrados > 0\n\ndef verificar_documentos_ui():\n    \"\"\"Verificar el archivo de documentos\"\"\"\n    print(\"\\n🔍 VERIFICANDO DOCUMENTOS UI\")\n    print(\"=\" * 35)\n    \n    if not os.path.exists('documentos_ui.py'):\n        print(\"❌ documentos_ui.py no encontrado\")\n        return False\n    \n    with open('documentos_ui.py', 'r', encoding='utf-8') as f:\n        contenido = f.read()\n    \n    # Verificar funciones clave\n    funciones_clave = [\n        'refresh_documents',\n        'load_case_documents',\n        'update_display_for_case'\n    ]\n    \n    funciones_encontradas = 0\n    for funcion in funciones_clave:\n        if f'def {funcion}' in contenido:\n            print(f\"✅ Función {funcion}() encontrada\")\n            funciones_encontradas += 1\n        else:\n            print(f\"❌ Función {funcion}() no encontrada\")\n    \n    if funciones_encontradas == len(funciones_clave):\n        print(\"✅ documentos_ui.py tiene funcionalidad completa\")\n        return True\n    else:\n        print(f\"⚠️ documentos_ui.py: {funciones_encontradas}/{len(funciones_clave)} funciones encontradas\")\n        return False\n\ndef main():\n    \"\"\"Función principal de verificación\"\"\"\n    print(\"🔍 VERIFICADOR DE CORRECCIONES - CRM LEGAL\")\n    print(\"=\" * 60)\n    print(\"Verificando que las correcciones se aplicaron correctamente...\\n\")\n    \n    verificaciones = {\n        'update_case': verificar_update_case(),\n        'layout_calendario': verificar_layout_calendario(),\n        'base_datos': verificar_base_datos(),\n        'archivos_pestanas': verificar_archivos_pestanas(),\n        'documentos_ui': verificar_documentos_ui()\n    }\n    \n    # Reporte final\n    print(\"\\n📊 REPORTE DE VERIFICACIONES\")\n    print(\"=\" * 40)\n    \n    exitosas = sum(verificaciones.values())\n    total = len(verificaciones)\n    \n    for nombre, resultado in verificaciones.items():\n        estado = \"✅\" if resultado else \"❌\"\n        print(f\"   {estado} {nombre}\")\n    \n    print(f\"\\n🎯 RESULTADO: {exitosas}/{total} verificaciones exitosas\")\n    \n    if exitosas >= 4:\n        print(\"\\n🎉 CORRECCIONES VERIFICADAS EXITOSAMENTE\")\n        print(\"=\" * 50)\n        print(\"✅ Los problemas específicos han sido solucionados\")\n        print(\"\\n🚀 RECOMENDACIONES:\")\n        print(\"1. Ejecuta: python main_app_refactorizado.py\")\n        print(\"2. Prueba las funcionalidades corregidas:\")\n        print(\"   • Alta/Edición de caso (sin error de argumentos)\")\n        print(\"   • Layout columna central (2/3 casos, 1/3 audiencias)\")\n        print(\"   • Sistema de etiquetas (sin errores BD)\")\n        print(\"   • Funcionalidad de documentos\")\n        \n        if not verificaciones['base_datos']:\n            print(\"\\n📋 NOTA SOBRE BASE DE DATOS:\")\n            print(\"• Si la BD no existe, se creará automáticamente\")\n            print(\"• Si existe pero falta fecha_creacion, ejecutar migración\")\n    \n    else:\n        print(f\"\\n⚠️ VERIFICACIÓN PARCIAL ({exitosas}/{total})\")\n        print(\"Algunas correcciones pueden necesitar ajustes adicionales\")\n        \n        print(\"\\n🔧 CORRECCIONES PENDIENTES:\")\n        for nombre, resultado in verificaciones.items():\n            if not resultado:\n                print(f\"   • {nombre}\")\n\nif __name__ == \"__main__\":\n    main()\n